import{_ as a,o as l,c as r,a6 as s}from"./chunks/framework.C3mgXFrM.js";const p=JSON.parse('{"title":"macOS Terminal 配置","description":"macOS Terminal 终端的配置文件与优化建议。","frontmatter":{"title":"macOS Terminal 配置","description":"macOS Terminal 终端的配置文件与优化建议。","layout":"doc"},"headers":[],"relativePath":"develop/system/macos_terminal.md","filePath":"develop/system/macos_terminal.md","lastUpdated":1782807412000}'),i={name:"develop/system/macos_terminal.md"};function t(o,e,n,c,d,h){return l(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="配置指南" tabindex="-1">配置指南 <a class="header-anchor" href="#配置指南" aria-label="Permalink to “配置指南”">​</a></h1><p>本文介绍如何配置 macOS 自带的 Terminal 应用，重点说明 Profiles 中的常用设置项，帮助提升终端使用体验。</p><h2 id="profiles-设置" tabindex="-1">Profiles 设置 <a class="header-anchor" href="#profiles-设置" aria-label="Permalink to “Profiles 设置”">​</a></h2><p>进入 Terminal 应用后，依次点击菜单栏：<strong>Terminal → Settings（设置） → Profiles（配置文件）</strong>，选择你正在使用的 Profile（如 Basic、Pro、或自定义的），可进行以下调整：</p><h3 id="_1-keyboard-→-scroll-alternate-screen" tabindex="-1">1. Keyboard → Scroll alternate screen <a class="header-anchor" href="#_1-keyboard-→-scroll-alternate-screen" aria-label="Permalink to “1. Keyboard → Scroll alternate screen”">​</a></h3><ul><li><strong>作用</strong>：控制当程序进入“备用屏幕模式”（alternate screen）时，是否允许使用滚动条查看历史输出内容。</li><li><strong>场景举例</strong>：在使用 <code>tmux</code>、<code>less</code> 或 <code>vim</code> 等程序时，它们通常会切换至备用屏幕模式，默认无法通过鼠标滚轮查看之前的输出。</li><li><strong>建议设置</strong>：取消勾选 <code>Scroll alternate screen</code>，可在 tmux 中禁用鼠标时依旧通过触控板或鼠标滚轮查看历史命令输出。</li></ul><hr><h2 id="其他推荐设置说明" tabindex="-1">其他推荐设置说明 <a class="header-anchor" href="#其他推荐设置说明" aria-label="Permalink to “其他推荐设置说明”">​</a></h2><h3 id="_2-text-→-字体与抗锯齿设置" tabindex="-1">2. Text → 字体与抗锯齿设置 <a class="header-anchor" href="#_2-text-→-字体与抗锯齿设置" aria-label="Permalink to “2. Text → 字体与抗锯齿设置”">​</a></h3><ul><li><strong>Font</strong>：建议使用等宽字体（如 <code>Menlo</code>、<code>SF Mono</code>、<code>JetBrains Mono</code> 等），字体大小建议 13pt 以上。</li><li><strong>Use ligatures</strong>：如你使用支持连字的字体，可勾选此项以改善代码可读性。</li><li><strong>Antialias text</strong>：建议保持勾选以获得更平滑的字体显示。</li></ul><h3 id="_3-colors-→-配色方案" tabindex="-1">3. Colors → 配色方案 <a class="header-anchor" href="#_3-colors-→-配色方案" aria-label="Permalink to “3. Colors → 配色方案”">​</a></h3><ul><li><strong>预设主题</strong>：macOS 提供多种配色方案，如 Pro、Homebrew、Novel、Ocean 等。</li><li><strong>建议</strong>：根据个人喜好选择适合的配色，同时可自定义背景透明度，使终端更美观易读。</li></ul><h3 id="_4-window-→-窗口样式" tabindex="-1">4. Window → 窗口样式 <a class="header-anchor" href="#_4-window-→-窗口样式" aria-label="Permalink to “4. Window → 窗口样式”">​</a></h3><ul><li><strong>Background opacity</strong>：可设置背景不透明度，如设置为 90% 提升专注力。</li><li><strong>Use option as meta key</strong>：若你使用 Emacs 快捷键或 tmux，建议启用此选项将 Option 键作为 <code>Meta</code>。</li></ul><h3 id="_5-shell-→-启动命令" tabindex="-1">5. Shell → 启动命令 <a class="header-anchor" href="#_5-shell-→-启动命令" aria-label="Permalink to “5. Shell → 启动命令”">​</a></h3><ul><li><strong>Startup command</strong>：可自定义启动时运行的 shell 命令，如启动 <code>tmux</code>、<code>zellij</code> 或进入某个虚拟环境。<div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tmux</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> attach</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> ||</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> tmux</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div></li></ul>',16)])])}const g=a(i,[["render",t]]);export{p as __pageData,g as default};
